INSERT IGNORE INTO graha_graha (graha_id, graha2_id, interpretation_np, interpretation_en, positive_effects, challenges, career_indication, financial_indication, relationship_indication, classical_interpretation, sanskrit_reference, remedies) VALUES
(1,1,'सूर्य र सूर्य ग्रह दुईपटक संयोजन भएकाले ग्रहको प्रभाव दोब्बर हुन्छ। आत्मविश्वास र नेतृत्व बलियो बन्छ, तर अहंकार पनि दोब्बर हुन्छ।',NULL,'दोब्बर आत्मविश्वास, नेतृत्व, प्रतिष्ठा','अति अहंकार, अन्यसँग टकराव','राजनीति, प्रशासन, नेतृत्व पद','सरकारी स्रोतबाट बलियो आय','आफ्नो मत माथि जिद','सूर्ययुतिः सूर्यबलं ददाति','Brihat Parashara Hora Shastra — Yuti Adhyaya','रविवार सूर्यलाई जल अर्पण र आदित्य हृदय स्तोत्र पाठ गर्ने।'),
(1,2,'सूर्य र चन्द्र को संयोजन आत्मा र मनको मिलन हो — पिता र माताका कारक सँगै जोडिन्छन्। मनमा स्पष्टता आउँछ, तर परिवारमा भावनात्मक उतारचढाव रहन सक्छ।',NULL,'पारिवारिक सद्भाव, भावनात्मक स्पष्टता','भावनामा उतारचढाव, पितृसँग दूरी','जनसेवा, प्रशासन, कला','पारिवारिक स्रोतबाट लाभ','परिवारमा करुणा र स्नेह','सूर्यचन्द्रयुतौ मातृपितृसुखं ददातः','Brihat Parashara Hora Shastra — Yuti Adhyaya','रविवार र सोमबार जल अर्पण गर्ने।'),
(1,3,'सूर्य र मङ्गल को संयोजन पराक्रम र नेतृत्वको योग बनाउँछ। साहससँगै नेतृत्व क्षमता बढ्छ, राज्यसेवा र सेनामा सफलता मिल्छ तर क्रोधमा संयम चाहिन्छ।',NULL,'साहस, नेतृत्व, विजय','क्रोध, टकराव, जोखिम','सेना, प्रशासन, खेलकुद','पराक्रमबाट लाभ','तीव्र निर्णयले सम्बन्धमा दबाब','सूर्यमङ्गलयुते वीर्यवान् भवति','Brihat Parashara Hora Shastra — Yuti Adhyaya','रविवार जल अर्पण र मङ्गलबार हनुमान चालीसा पाठ गर्ने।'),
(1,4,'सूर्य र बुध को संयोजन बुधादित्य योग हो — बुद्धि र वाणीमा तेज दिन्छ। व्यापार, लेखन र प्रशासनमा बुद्धिमत्तापूर्ण निर्णयको क्षमता आउँछ।',NULL,'तीव्र बुद्धि, वाणी तेज, व्यापारिक सफलता','अति विचार, द्विधा','लेखन, व्यापार, प्रशासन','बुद्धिबाट आय, बहु स्रोत','स्पष्ट संवाद, तर कम भावना','बुधादित्ययोगो बुद्धिमान् भवति','Brihat Parashara Hora Shastra — Yuti Adhyaya','बुधवार गणेशलाई दूर्वा चढाउने र रविवार सूर्यलाई जल दिने।'),
(1,5,'सूर्य र गुरु को संयोजन धर्म र ज्ञानको मिलन हो — नैतिक नेतृत्व र आध्यात्मिक विश्वास दिन्छ। गुरुजनको सान्निध्य र सम्मान पाइन्छ।',NULL,'धर्म, ज्ञान, नैतिक नेतृत्व','अति उदारता, दम्भ','शिक्षण, धर्म, प्रशासन','भाग्यबाट लाभ, सम्मानजनक आय','आदर र विश्वासमा आधारित','गुरुसूर्ययुतौ धर्मप्रियो भवति','Brihat Parashara Hora Shastra — Yuti Adhyaya','गुरुवार विष्णु मन्त्र र रविवार सूर्य जल अर्पण गर्ने।'),
(1,6,'सूर्य र शुक्र को संयोजन प्रतिष्ठा र कलाको मिलन हो — कलात्मकता र सामाजिक मान्यता दिन्छ, तर वैवाहिक विषयमा अहम् आउँछ।',NULL,'कलात्मकता, सम्मान, वैभव','अहम्, अति भोग','कला, प्रशासन, मनोरञ्जन','प्रतिष्ठाजनक आय','प्रेममा अहम् झगडा','सूर्यशुक्रयुतौ कीर्तिवान् भवति','Brihat Parashara Hora Shastra — Yuti Adhyaya','रविवार जल अर्पण र शुक्रबार लक्ष्मी मन्त्र जप गर्ने।'),
(1,7,'सूर्य र शनि को संयोजन कर्म र पितृको कठोर मिलन हो — पितृसँग तनाव र कर्ममा ढिलाइ दिन्छ, तर अनुशासनबाट पछि दिगो सम्मान मिल्छ।',NULL,'दिगो प्रतिष्ठा, कर्म फल, धैर्य','पितृ तनाव, ढिलाइ, स्वास्थ्य','प्रशासन, श्रम, दीर्घ परियोजना','ढिले तर स्थिर लाभ','परिवारमा दूरी, पछि मिलाप','सूर्यशनिसंयोगे कर्मफलं दीर्घे भवति','Brihat Parashara Hora Shastra — Yuti Adhyaya','रविवार जल अर्पण र शनिवार तिल तेल दान गर्ने।'),
(1,8,'सूर्य र राहु को संयोजन ग्रहण योग हो — पहिचानमा भ्रम र अचानक उतारचढाव दिन्छ, तर विदेश र प्रविधिमा अप्रत्याशित उन्नति पनि दिन्छ।',NULL,'विदेश अवसर, प्रविधि, अचानक उन्नति','भ्रम, असन्तोष, अहंकारमा उतारचढाव','प्रविधि, विदेशी कार्य, राजनीति','अचानक लाभ, तर अनिश्चितता','मोह र अस्थिरता','राहुसूर्ययुतौ ग्रहणदोषो भवति','Brihat Parashara Hora Shastra — Yuti Adhyaya','रविवार जल अर्पण र दुर्गा सप्तशती पाठ गर्ने।'),
(1,9,'सूर्य र केतु को संयोजन ग्रहण योग हो — आत्मचिन्तन र आध्यात्मिक दृष्टिकोण बढ्छ, तर बाह्य प्रतिष्ठामा अस्थिरता रहन्छ।',NULL,'आध्यात्मिक ज्ञान, अन्तर्दृष्टि','पहिचान भ्रम, अस्थिर प्रतिष्ठा','अनुसन्धान, आध्यात्मिक कार्य','अनिश्चित आय, त्याग','भावनामा दूरी','सूर्यकेतूयुतौ आत्मचिन्तनं ददाति','Brihat Parashara Hora Shastra — Yuti Adhyaya','रविवार जल अर्पण र गणेश चालीसा पाठ गर्ने।'),
(2,1,'चन्द्र र सूर्य को संयोजन आत्मा र मनको मिलन हो — पिता र माताका कारक सँगै जोडिन्छन्। मनमा स्पष्टता आउँछ, तर परिवारमा भावनात्मक उतारचढाव रहन सक्छ।',NULL,'पारिवारिक सद्भाव, भावनात्मक स्पष्टता','भावनामा उतारचढाव, पितृसँग दूरी','जनसेवा, प्रशासन, कला','पारिवारिक स्रोतबाट लाभ','परिवारमा करुणा र स्नेह','सूर्यचन्द्रयुतौ मातृपितृसुखं ददातः','Brihat Parashara Hora Shastra — Yuti Adhyaya','रविवार र सोमबार जल अर्पण गर्ने।'),
(2,2,'चन्द्र र चन्द्र ग्रह दुईपटक संयोजन भएकाले मन र भावना दोब्बर बलियो हुन्छन्। स्मृति र लोकप्रियता बढ्छ, तर मन चञ्चल र भावनात्मक अस्थिरता पनि दोब्बर हुन्छ।',NULL,'बलियो स्मृति, लोकप्रियता, करुणा','अति भावनात्मकता, नींद कम','जनसेवा, शिक्षा, कला','चल सम्पत्ति, जलजन्य आय','गहिरो स्नेह, तर उतारचढाव','चन्द्रयुतिः चन्द्रबलं ददाति','Brihat Parashara Hora Shastra — Yuti Adhyaya','सोमबार शिवलिंगमा जल चढाउने र चन्द्र मन्त्र जप गर्ने।'),
(2,3,'चन्द्र र मङ्गल को संयोजन चन्द्रमङ्गल योग हो — भूमि र सामान्य स्रोतबाट धन दिन्छ, तर शरीरमा चोट र मनोव्यथाको जोखिम पनि रहन्छ।',NULL,'भूमि लाभ, साहस, भावनात्मक शक्ति','क्रोध, चोट, मनोव्यथा','भूमि-निर्माण, खेलकुद, सेवा','भूमिबाट धन, विवादले खर्च','तीव्र भावना, कहिलेकाहीं झगडा','चन्द्रमङ्गलयुतौ भूमिलाभो भवति','Brihat Parashara Hora Shastra — Yuti Adhyaya','सोमबार जल अर्पण र मङ्गलबार हनुमान चालीसा पाठ गर्ने।'),
(2,4,'चन्द्र र बुध को संयोजन मन र बुद्धिको मिलन हो — सञ्चार र लेखनमा दक्षता दिन्छ, तर मन दोहोरो विचारले चञ्चल रहन्छ।',NULL,'सञ्चार दक्षता, लेखन कला, बहुमुखी बुद्धि','द्विधा, भावनात्मक अस्थिरता','लेखन, सञ्चार, शिक्षा','बहुआय, अनियमित','संवाद राम्रो, तर भावना चञ्चल','चन्द्रबुधयुतौ वाक्पटु भवति','Brihat Parashara Hora Shastra — Yuti Adhyaya','सोमबार जल अर्पण र बुधवार गणेश दूर्वा चढाउने।'),
(2,5,'चन्द्र र गुरु को संयोजन शुभ गुरु-चन्द्र योग हो — करुणा, ज्ञान र लोकप्रियता दिन्छ। माताको स्नेह र शिक्षामा उन्नति हुन्छ।',NULL,'करुणा, ज्ञान, लोकप्रियता, मातृ स्नेह','अति भावुकता, अति आशावाद','शिक्षण, जनसेवा, धर्म','भाग्यबाट लाभ','पारिवारिक सद्भाव, गहिरो स्नेह','गुरुचन्द्रयुतौ शुभबुद्धिर्भवति','Brihat Parashara Hora Shastra — Yuti Adhyaya','सोमबार जल अर्पण र गुरुवार विष्णु मन्त्र जप गर्ने।'),
(2,6,'चन्द्र र शुक्र को संयोजन मन र कलाको मिलन हो — कलात्मकता, सौन्दर्यप्रियता र भावनात्मक स्नेह दिन्छ। सङ्गीत र कलामा रुचि बढ्छ।',NULL,'कलात्मकता, सौन्दर्य, प्रेम','अति सान्द्रता, मनोद्वन्द्व','कला, सङ्गीत, मनोरञ्जन','कलाबाट लाभ','प्रेमपूर्ण र भावनात्मक सम्बन्ध','चन्द्रशुक्रयुतौ कलावान् भवति','Brihat Parashara Hora Shastra — Yuti Adhyaya','सोमबार जल अर्पण र शुक्रबार लक्ष्मी मन्त्र जप गर्ने।'),
(2,7,'चन्द्र र शनि को संयोजन मनमा ठूलाइको भाव दिन्छ — भावनामा संयम र गम्भीरता आउँछ, तर अकेलापन र चिन्ता पनि साथै हुन्छ।',NULL,'भावनात्मक परिपक्वता, धैर्य, दिगो सम्बन्ध','अकेलापन, चिन्ता, भावनामा दमन','प्रशासन, श्रम, अनुसन्धान','हौले जम्ने धन','भावना व्यक्त गर्न कठिन','चन्द्रशनियुतौ मनोविषादं ददाति','Brihat Parashara Hora Shastra — Yuti Adhyaya','सोमबार जल अर्पण र शनिवार तिल तेल दान गर्ने।'),
(2,8,'चन्द्र र राहु को संयोजन मन र भ्रमको मिलन हो — अत्यधिक कल्पना र असन्तोष दिन्छ, तर अनुसन्धान र प्रविधिमा रुचि पनि जगाउँछ।',NULL,'कल्पना शक्ति, अनुसन्धान, प्रविधिमा रुचि','भ्रम, असन्तोष, निद्रा कम','अनुसन्धान, प्रविधि, मीडिया','अनियमित लाभ, अचानक उतारचढाव','भावनामा भ्रम, मोह','चन्द्रराहुयुतौ मनभ्रमं ददाति','Brihat Parashara Hora Shastra — Yuti Adhyaya','सोमबार जल अर्पण र दुर्गा सप्तशती पाठ गर्ने।'),
(2,9,'चन्द्र र केतु को संयोजन मन र वैराग्यको मिलन हो — आध्यात्मिक अनुभूति बढ्छ, भौतिक कुरामा उदासीनता रहन्छ।',NULL,'आध्यात्मिक अनुभूति, अन्तर्दृष्टि, शान्ति','उदासीनता, भावनात्मक दूरी','आध्यात्मिक कार्य, अनुसन्धान','त्यागमुखी खर्च','भावना कम, तर गहिरो सम्झना','चन्द्रकेतूयुतौ वैराग्यबुद्धिः','Brihat Parashara Hora Shastra — Yuti Adhyaya','सोमबार जल अर्पण र गणेश चालीसा पाठ गर्ने।'),
